const g = $input.first().json;
const final = g.fixed ?? g.output ?? g.text ?? '';
const m = $('smart_rules').first().json;
const prev = $('دریافت متن فارسی').first().json;
const reg = $('دروازهٔ رگرسیون').first().json;
const ledger = $('دفتر تغییرات').first().json;
let passes = 1;
for (const n of ['ویراستار ۲', 'ویراستار ۳', 'ویراستار ۴']) {
  try { const it = $(n).first(); if (it && it.json) passes++; } catch (e) { break; }
}
const mechClean = g.clean ?? true;
const regPass = reg.pass ?? false;
return [{ json: {
  text: final,
  task_type: prev.task_type ?? '',
  rules_used: m.rules_count ?? 0,
  passes,
  mechanical_clean: mechClean,
  regression_pass: regPass,
  regression_resolved: reg.resolved_count ?? 0,
  regression_remaining: reg.remaining ?? [],
  change_count: ledger.change_count ?? 0,
  changes: (ledger.changes ?? []).slice(0, 20),
  needs_human_review: !mechClean || !regPass
} }];
